-- ESPN numbers venues per sport: id 10660 is Gillette Stadium on the soccer scoreboard and Accor
-- Arena (Paris) on the basketball one. One shared `espn_venue_ids` map resolved New England's 2026
-- home matches to Paris on hosted (17 matches; local had none because its seed loaded in a different
-- order). Soccer ids now live under `provider_ids.espn_soccer_venue_ids`, generated here from
-- seed/mls_venues.json through seed/scripts/venues.py, and the matches go back to Foxborough.

update public.venues set provider_ids = (provider_ids - 'espn_venue_ids') || jsonb_build_object('espn_soccer_venue_ids', '["4418"]'::jsonb) || case when (select count(*) from jsonb_array_elements_text(coalesce(provider_ids->'espn_venue_ids','[]'::jsonb)) e where e.value not in (select jsonb_array_elements_text('["4418"]'::jsonb))) > 0 then jsonb_build_object('espn_venue_ids', (select jsonb_agg(e.value) from jsonb_array_elements_text(provider_ids->'espn_venue_ids') e where e.value not in (select jsonb_array_elements_text('["4418"]'::jsonb)))) else '{}'::jsonb end where key = 'bank-of-america-stadium';
