-- A venue the MLS ingest created itself since the seed (`new_venues` in the daily job) carries the
-- old key with only soccer ids: rename it.
update public.venues set provider_ids = (provider_ids - 'espn_venue_ids') || jsonb_build_object('espn_soccer_venue_ids', provider_ids->'espn_venue_ids') where key like 'mls-espn-%' and provider_ids ? 'espn_venue_ids';

-- The misplaced matches: every MLS match at Accor Arena was a New England home match.
update public.games g set venue_id = (select id from public.venues where key = 'gillette-stadium')
  where g.sport_id = 'mls' and g.venue_id = (select id from public.venues where key = 'accor-arena');
